        let idle = idle_from(marker).unwrap();
        assert!(valid_idle(host, &idle));
        assert!(!valid_idle(Host { pid: 1, birth: 3 }, &idle));
        assert!(!valid_idle(host, marker));
        assert!(!valid_idle(host, b"word-provider-idle/v1\n1\n2\n0\n"));
    }
}

