 let segment_start=byte_start;let segment=&trimmed[segment_start..];
 if automatic&&crate::code_safe::is_code_safe_token(segment){return None;}
 // Reconstruct intra-token punctuation boundaries from fresh text. Retain OEM
 // comma/period only when the actual detector recognizes a target prefix.
 for (offset,ch) in segment.char_indices(){
  if matches!(ch,','|'.'|'?'|'!'|';'|':')&&offset+ch.len_utf8()<segment.len(){
   let end=segment_start+offset+ch.len_utf8();
   let prospective=&trimmed[byte_start..end];
   let extends=layout_language==Language::English&&matches!(ch,','|'.')&&crate::detector::opposite_candidate_is_prefix_for_language(prospective,layout_language,words);
   if !extends{byte_start=end;}
  }
