pub fn run_word_broker()->Result<()>{word_broker::run_role()}

// Pure routing only, shared by the actual posted-key path and regression tests.
// A request does not suppress input or confer provider/security authority.
fn word_request_kind(vk:u16,modifiers:Modifiers,settings:&settings::RuntimeSettings,paused:bool)->Option<word_broker::Kind>{
 if paused||settings.app_mode("winword.exe")==AppMode::Disabled{return None;}
 let hotkey=|h:settings::Hotkey|h.matches(vk,modifiers.ctrl,modifiers.shift,modifiers.alt);
 if hotkey(settings.selected_text_hotkey){return Some(word_broker::Kind::Selected);}
 if hotkey(settings.manual_current_hotkey){return Some(word_broker::Kind::Manual);}
 if hotkey(settings.previous_word_hotkey){return Some(word_broker::Kind::Previous);}
 if hotkey(settings.undo_hotkey){return Some(word_broker::Kind::Undo);}
 if is_modifier_vk(vk)||modifiers.ctrl||modifiers.alt||(vk!=VK_TAB&&invalidates_context(vk,modifiers)){return None;}
 (settings.app_mode("winword.exe")==AppMode::Auto&&settings.auto_correct).then_some(if matches!(vk,VK_SPACE|VK_RETURN|VK_TAB){word_broker::Kind::Boundary}else{word_broker::Kind::Auto})
}

impl Engine{
 fn on_word_event(&mut self,event:HookEvent,target:FocusTarget,settings:&settings::RuntimeSettings){
  self.on_word_event_with_dispatch(event,target,settings,settings::paused(),|kind|word_broker::submit(target,event.generation,kind,settings,None));
 }
 fn on_word_event_with_dispatch(&mut self,event:HookEvent,target:FocusTarget,settings:&settings::RuntimeSettings,paused:bool,mut dispatch:impl FnMut(word_broker::Kind)->bool){
  // Unknown Word hotkeys pass through in the hook. Explicit requests are values,
  // not authority; Word's own shortcut may invalidate them before broker checks.
  HOOK_POLICY.store(POLICY_UNKNOWN,Ordering::SeqCst);
  self.reset_candidate();self.previous=None;self.context_tokens.clear();self.undo=None;self.selection_undo=None;
  let matches=|hotkey:settings::Hotkey|hotkey.matches(event.vk,event.modifiers.ctrl,event.modifiers.shift,event.modifiers.alt);
  if matches(settings.pause_hotkey){let paused=settings::toggle_paused();tray_status::set_paused(paused);return;}
  if paused{return;}
  let kind=word_request_kind(event.vk,event.modifiers,settings,paused);
  if kind==Some(word_broker::Kind::Undo){let _=self.queue_word_undo(target,event.generation,settings);return;}
  if !is_modifier_vk(event.vk){self.word_undo=None;}
  if let Some(kind)=kind{let _=dispatch(kind);}
 }
 fn queue_word_undo(&mut self,target:FocusTarget,generation:u32,settings:&settings::RuntimeSettings)->bool{
  let Some(undo)=self.word_undo.take()else{return false;};
  if undo.hwnd!=target.hwnd as i64||undo.pid!=target.process_id||undo.generation!=generation||selection::word_admission::identity(target.hwnd as isize)!=Some((undo.pid,undo.birth)){return false;}
  word_broker::submit(target,generation,word_broker::Kind::Undo,settings,Some(undo.value))
 }
 fn apply_word_result(&mut self){
  let Some(result)=word_broker::poll()else{return;};
  if result.uncertain||!result.success{return;}
  if result.generation!=current_generation()||word_broker::current_input()!=Some(result.input)||focused_target().is_none_or(|t|t.hwnd as i64!=result.hwnd||t.process_id!=result.pid)||selection::word_admission::identity(result.hwnd as isize)!=Some((result.pid,result.birth)){return;}
  let Some(value)=result.undo else{return;};
  if result.undone{self.word_undo=None;tray_status::note_undo(infer_language(&value.original).unwrap_or(Language::English));return;}
  self.word_undo=Some(BrokerUndo{hwnd:result.hwnd,pid:result.pid,birth:result.birth,generation:result.generation,value});
  let language=if result.target_language==1{Language::Russian}else{Language::English};tray_status::note_correction(language);sound::play_correction(&settings::runtime_settings());
 }
}

